const app = require('./app');

// Simplified test structure without using supertest or jest extended matchers

describe('/users endpoint', () => {
  let originalConsoleError;

  // Capture console.error to test error handling
  beforeEach(() => {
    originalConsoleError = console.error;
    console.error = jest.fn();
  });

  afterEach(() => {
    console.error = originalConsoleError;
  });

  // Test happy path
  test('returns 200 and user array on successful request', async () => {
    // Since we cannot use supertest, we will test the route handler directly
    // Extract the /users route handler from the app
    const usersRouteHandler = app._router.stack.find(
      r => r.route && r.route.path === '/users' && r.route.methods.get
    ).route.stack[0].handle;

    // Create mock request and response objects
    const mockReq = {};
    const mockRes = {
      json: jest.fn(),
      status: jest.fn().mockReturnThis()
    };

    // Call the handler
    await usersRouteHandler(mockReq, mockRes);

    // Assert the response
    expect(mockRes.status).not.toHaveBeenCalled(); // Should not call status for 200
    expect(mockRes.json).toHaveBeenCalledWith([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ]);
  });

  // Test response format/schema
  test('returns user objects with correct schema', async () => {
    const usersRouteHandler = app._router.stack.find(
      r => r.route && r.route.path === '/users' && r.route.methods.get
    ).route.stack[0].handle;

    const mockReq = {};
    const mockRes = {
      json: jest.fn(),
      status: jest.fn().mockReturnThis()
    };

    await usersRouteHandler(mockReq, mockRes);

    const responseData = mockRes.json.mock.calls[0][0];

    // Check that it's an array
    expect(Array.isArray(responseData)).toBe(true);
    expect(responseData.length).toBe(2);

    // Check schema of each user object
    responseData.forEach(user => {
      expect(user).toHaveProperty('id');
      expect(typeof user.id).toBe('number');
      expect(user).toHaveProperty('name');
      expect(typeof user.name).toBe('string');
      expect(user).toHaveProperty('email');
      expect(typeof user.email).toBe('string');
      // Simple email format check
      expect(user.email).toMatch(/^[^@]+@[^@]+\.[^@]+$/);
    });
  });

  // Test error handling - though the current implementation doesn't throw errors,
  // we can verify that errors are handled appropriately
  test('handles errors properly if they occur', async () => {
    // Create a version of the handler that throws an error
    const errorHandler = (req, res) => {
      throw new Error('Test error');
    };

    // Mock the app to use our error handler temporarily
    const usersRoute = app._router.stack.find(
      r => r.route && r.route.path === '/users' && r.route.methods.get
    );
    const originalHandler = usersRoute.route.stack[0].handle;
    usersRoute.route.stack[0].handle = errorHandler;

    // We need to simulate the app's error handling, which Express handles automatically
    // For this mock test, we'll just verify that console.error is called
    try {
      await originalHandler.call({ handle: errorHandler }, {}, {});
    } catch (e) {
      // Expected to throw
    }

    // Clean up
